SELECT gen_random_uuid()::text, 'formula', '$h_A$', 'Energy Equation with Pump and Losses', '$\frac{p_1}{\gamma} + \frac{v_1^2}{2g} + z_1 + h_A = \frac{p_2}{\gamma} + \frac{v_2^2}{2g} + z_2 + h_L + h_E$', '$\text{m}$', 'Bernoulli with pumps, turbines and friction included.', '[{"symbol":"$h_A$","meaning":"head added by a pump","unit":"$\\text{m}$"},{"symbol":"$h_E$","meaning":"head extracted by a turbine","unit":"$\\text{m}$"},{"symbol":"$h_L$","meaning":"head lost","unit":"$\\text{m}$"}]'::jsonb, 'At a reservoir surface or a free jet the pressure head is zero (gauge).', 'ESAS', t."id", (SELECT s."id" FROM "SyllabusSubtopic" s JOIN "Topic" t ON t."id" = s."topicId" WHERE t."name" = 'Fluid Mechanics' AND t."subject" = 'ESAS' AND s."normKey" = 'bernoulli and energy equations' AND s."active"), NULL, false, 'PENDING', now(), now()
