SELECT gen_random_uuid()::text, 'formula', '$EGL$', 'Hydraulic and Energy Grade Lines', '$HGL = \frac{p}{\gamma} + z,\qquad EGL = HGL + \frac{v^2}{2g}$', '$\text{m}$', 'The heights a piezometer and a pitot tube would show along a pipe.', '[{"symbol":"$\\gamma$","meaning":"specific weight","unit":"$\\text{N/m}^3$"},{"symbol":"$v$","meaning":"mean velocity","unit":"$\\text{m/s}$"},{"symbol":"$z$","meaning":"elevation","unit":"$\\text{m}$"}]'::jsonb, 'Where the HGL drops below the pipe, the pressure is below atmospheric.', 'ESAS', t."id", (SELECT s."id" FROM "SyllabusSubtopic" s JOIN "Topic" t ON t."id" = s."topicId" WHERE t."name" = 'Fluid Mechanics' AND t."subject" = 'ESAS' AND s."normKey" = 'bernoulli and energy equations' AND s."active"), NULL, false, 'PENDING', now(), now()
