SELECT gen_random_uuid()::text, 'formula', '$Q$', 'Venturi Meter', '$Q = C_dA_2\sqrt{\frac{2g\Delta h}{1 - (A_2/A_1)^2}}$', '$\text{m}^3\text{/s}$', 'Flow rate from the pressure drop at a pipe''s narrowing throat.', '[{"symbol":"$A_1, A_2$","meaning":"inlet and throat areas","unit":"$\\text{m}^2$"},{"symbol":"$\\Delta h$","meaning":"piezometric head difference","unit":"$\\text{m}$"},{"symbol":"$C_d$","meaning":"discharge coefficient (≈ 0.98)","unit":null}]'::jsonb, 'With a mercury manometer reading $R$ in water: $\Delta h = R(13.6 - 1)$.', 'ESAS', t."id", (SELECT s."id" FROM "SyllabusSubtopic" s JOIN "Topic" t ON t."id" = s."topicId" WHERE t."name" = 'Fluid Mechanics' AND t."subject" = 'ESAS' AND s."normKey" = 'bernoulli and energy equations' AND s."active"), NULL, false, 'PENDING', now(), now()
