SELECT gen_random_uuid()::text, 'formula', '$F_x$', 'Force on a Pipe Bend', '$F_x = p_1A_1 - p_2A_2\cos\theta + \rho Q(v_1 - v_2\cos\theta),\qquad F_y = (p_2A_2 + \rho Qv_2)\sin\theta$', '$\text{N}$', 'The anchoring force a bend needs, from pressure and the change of momentum.', '[{"symbol":"$p_1, p_2$","meaning":"pressures at inlet and outlet","unit":"$\\text{Pa}$"},{"symbol":"$\\theta$","meaning":"angle of the bend","unit":null},{"symbol":"$Q$","meaning":"flow rate","unit":"$\\text{m}^3\\text{/s}$"}]'::jsonb, 'Apply ΣF = ρQ(v_out − v_in) on the fluid, component by component; the bend''s force on the fluid is the reverse.', 'ESAS', t."id", (SELECT s."id" FROM "SyllabusSubtopic" s JOIN "Topic" t ON t."id" = s."topicId" WHERE t."name" = 'Fluid Mechanics' AND t."subject" = 'ESAS' AND s."normKey" = 'momentum' AND s."active"), NULL, false, 'PENDING', now(), now()
