SELECT gen_random_uuid()::text, 'formula', '$F$', 'Force on a Moving Vane', '$F = \rho A(v - u)^2(1 - \cos\theta)$', '$\text{N}$', 'The push of a jet on a single vane moving away from it.', '[{"symbol":"$\\rho$","meaning":"density","unit":"$\\text{kg/m}^3$"},{"symbol":"$A$","meaning":"area","unit":"$\\text{m}^2$"},{"symbol":"$v$","meaning":"jet speed","unit":"$\\text{m/s}$"},{"symbol":"$u$","meaning":"vane speed","unit":"$\\text{m/s}$"},{"symbol":"$\\theta$","meaning":"angle the vane turns the jet","unit":null}]'::jsonb, 'A series of vanes (a wheel) catches the full flow ρAv; its power peaks at u = v/2.', 'ESAS', t."id", (SELECT s."id" FROM "SyllabusSubtopic" s JOIN "Topic" t ON t."id" = s."topicId" WHERE t."name" = 'Fluid Mechanics' AND t."subject" = 'ESAS' AND s."normKey" = 'momentum' AND s."active"), NULL, false, 'PENDING', now(), now()
