SELECT gen_random_uuid()::text, 'formula', '$F$', 'Reaction of a Jet from a Tank', '$F = \rho Qv = 2\gamma hA$', '$\text{N}$', 'The thrust on a tank from a jet leaving through a side opening.', '[{"symbol":"$h$","meaning":"head above the opening","unit":"$\\text{m}$"},{"symbol":"$A$","meaning":"jet area","unit":"$\\text{m}^2$"},{"symbol":"$\\gamma$","meaning":"specific weight","unit":"$\\text{N/m}^3$"}]'::jsonb, 'It is twice the hydrostatic force on a plug of the same area.', 'ESAS', t."id", (SELECT s."id" FROM "SyllabusSubtopic" s JOIN "Topic" t ON t."id" = s."topicId" WHERE t."name" = 'Fluid Mechanics' AND t."subject" = 'ESAS' AND s."normKey" = 'momentum' AND s."active"), NULL, false, 'PENDING', now(), now()
