SELECT gen_random_uuid()::text, 'formula', '$h_f$', 'Laminar Pipe Flow (Hagen-Poiseuille)', '$f = \frac{64}{Re},\qquad h_f = \frac{32\mu Lv}{\gamma D^2},\qquad v_{\max} = 2v$', '$\text{m}$', 'Friction loss and velocity profile in laminar flow.', '[{"symbol":"$\\mu$","meaning":"dynamic viscosity","unit":"$\\text{Pa}\\cdot\\text{s}$"},{"symbol":"$L$","meaning":"length","unit":"$\\text{m}$"},{"symbol":"$v$","meaning":"mean velocity","unit":"$\\text{m/s}$"},{"symbol":"$D$","meaning":"pipe diameter","unit":"$\\text{m}$"},{"symbol":"$\\gamma$","meaning":"specific weight","unit":"$\\text{N/m}^3$"}]'::jsonb, 'The velocity profile is a parabola, fastest at the centre.', 'ESAS', t."id", (SELECT s."id" FROM "SyllabusSubtopic" s JOIN "Topic" t ON t."id" = s."topicId" WHERE t."name" = 'Fluid Mechanics' AND t."subject" = 'ESAS' AND s."normKey" = 'pipe flow and head losses' AND s."active"), NULL, false, 'PENDING', now(), now()
