SELECT gen_random_uuid()::text, 'formula', '$h_m$', 'Minor Losses', '$h_m = K\frac{v^2}{2g};\quad \text{sudden enlargement } \frac{(v_1 - v_2)^2}{2g};\quad \text{exit } \frac{v^2}{2g};\quad \text{sharp entrance } 0.5\frac{v^2}{2g}$', '$\text{m}$', 'Head lost at fittings, valves, entrances, exits and changes of section.', '[{"symbol":"$K$","meaning":"loss coefficient of the fitting","unit":null},{"symbol":"$v$","meaning":"mean velocity","unit":"$\\text{m/s}$"},{"symbol":"$g$","meaning":"acceleration due to gravity","unit":"$\\text{m/s}^2$"}]'::jsonb, 'In short pipes the minor losses can exceed the friction loss.', 'ESAS', t."id", (SELECT s."id" FROM "SyllabusSubtopic" s JOIN "Topic" t ON t."id" = s."topicId" WHERE t."name" = 'Fluid Mechanics' AND t."subject" = 'ESAS' AND s."normKey" = 'pipe flow and head losses' AND s."active"), NULL, false, 'PENDING', now(), now()
