SELECT gen_random_uuid()::text, 'formula', '$v$', 'Hazen-Williams Formula', '$v = 0.849\,C\,R^{0.63}S^{0.54}\ \text{(SI)}$', '$\text{m/s}$', 'An empirical formula for water in pipes, common in waterworks design.', '[{"symbol":"$C$","meaning":"Hazen-Williams coefficient (new steel ≈ 120)","unit":null},{"symbol":"$R$","meaning":"hydraulic radius, D/4 for a full pipe","unit":"$\\text{m}$"},{"symbol":"$S$","meaning":"slope of the energy line, h_f/L","unit":null}]'::jsonb, 'Valid for water at ordinary temperatures only.', 'ESAS', t."id", (SELECT s."id" FROM "SyllabusSubtopic" s JOIN "Topic" t ON t."id" = s."topicId" WHERE t."name" = 'Fluid Mechanics' AND t."subject" = 'ESAS' AND s."normKey" = 'pipe flow and head losses' AND s."active"), NULL, false, 'PENDING', now(), now()
