SELECT gen_random_uuid()::text, 'formula', '$h_f$', 'Manning Formula for Pipes', '$h_f = \frac{10.29\,n^2LQ^2}{D^{16/3}}$', '$\text{m}$', 'Friction loss in a full pipe from Manning''s roughness.', '[{"symbol":"$n$","meaning":"Manning roughness","unit":null},{"symbol":"$L$","meaning":"length","unit":"$\\text{m}$"},{"symbol":"$Q$","meaning":"flow rate","unit":"$\\text{m}^3\\text{/s}$"},{"symbol":"$D$","meaning":"pipe diameter","unit":"$\\text{m}$"}]'::jsonb, 'Doubling the diameter cuts the loss about 40-fold.', 'ESAS', t."id", (SELECT s."id" FROM "SyllabusSubtopic" s JOIN "Topic" t ON t."id" = s."topicId" WHERE t."name" = 'Fluid Mechanics' AND t."subject" = 'ESAS' AND s."normKey" = 'pipe flow and head losses' AND s."active"), NULL, false, 'PENDING', now(), now()
