SELECT gen_random_uuid()::text, 'formula', '$f$', 'Swamee-Jain Friction Factor', '$f = \frac{0.25}{\left[\log_{10}\left(\frac{\varepsilon}{3.7D} + \frac{5.74}{Re^{0.9}}\right)\right]^2}$', NULL, 'An explicit fit to the Colebrook equation for turbulent flow (the Moody chart in one line).', '[{"symbol":"$\\varepsilon$","meaning":"pipe roughness","unit":"$\\text{m}$"},{"symbol":"$D$","meaning":"pipe diameter","unit":"$\\text{m}$"},{"symbol":"$Re$","meaning":"Reynolds number","unit":null}]'::jsonb, 'Within about 3% of Colebrook for 10⁻⁶ < ε/D < 10⁻², 5000 < Re < 10⁸, and usually within 1%; the worst case is rough pipe at low Re.', 'ESAS', t."id", (SELECT s."id" FROM "SyllabusSubtopic" s JOIN "Topic" t ON t."id" = s."topicId" WHERE t."name" = 'Fluid Mechanics' AND t."subject" = 'ESAS' AND s."normKey" = 'pipe flow and head losses' AND s."active"), NULL, true, 'PENDING', now(), now()
