SELECT gen_random_uuid()::text, 'formula', '$\sum Q = 0$', 'Three-Reservoir Problem', '$Q_1 + Q_2 + Q_3 = 0 \text{ at the junction (inflow +)},\qquad h_{fi} = |z_i - P_J|$', '$\text{m}^3\text{/s}$', 'Three reservoirs joined at one point: guess the junction head until the flows balance.', '[{"symbol":"$z_i$","meaning":"reservoir water surface elevations","unit":"$\\text{m}$"},{"symbol":"$P_J$","meaning":"energy (piezometric) height at the junction","unit":"$\\text{m}$"}]'::jsonb, 'First test P_J at the middle reservoir''s level to learn which way that pipe flows.', 'ESAS', t."id", (SELECT s."id" FROM "SyllabusSubtopic" s JOIN "Topic" t ON t."id" = s."topicId" WHERE t."name" = 'Fluid Mechanics' AND t."subject" = 'ESAS' AND s."normKey" = 'pipes in series and parallel' AND s."active"), NULL, false, 'PENDING', now(), now()
