SELECT gen_random_uuid()::text, 'formula', '$Q$', 'Orifice Discharge and Coefficients', '$Q = C_dA\sqrt{2gh},\qquad C_d = C_cC_v;\qquad h_L = h\left(\frac{1}{C_v^2} - 1\right)$', '$\text{m}^3\text{/s}$', 'Real flow through an orifice, smaller than Torricelli''s ideal.', '[{"symbol":"$C_c, C_v, C_d$","meaning":"contraction, velocity and discharge coefficients","unit":null},{"symbol":"$A$","meaning":"area","unit":"$\\text{m}^2$"},{"symbol":"$h$","meaning":"head on the orifice","unit":"$\\text{m}$"}]'::jsonb, 'A sharp-edged orifice: Cc ≈ 0.62, Cv ≈ 0.98, Cd ≈ 0.61.', 'ESAS', t."id", (SELECT s."id" FROM "SyllabusSubtopic" s JOIN "Topic" t ON t."id" = s."topicId" WHERE t."name" = 'Fluid Mechanics' AND t."subject" = 'ESAS' AND s."normKey" = 'orifices and weirs' AND s."active"), NULL, false, 'PENDING', now(), now()
FROM "Topic" t WHERE t."name" = 'Fluid Mechanics' AND t."subject" = 'ESAS'
ON CONFLICT ("kind", "subject", "name") DO NOTHING;
