SELECT gen_random_uuid()::text, 'formula', '$t$', 'Time to Drain a Tank', '$t = \frac{2A_s(\sqrt{h_1} - \sqrt{h_2})}{C_dA_o\sqrt{2g}}$', '$\text{s}$', 'Time for a prismatic tank to fall from one head to another through an orifice.', '[{"symbol":"$A_s$","meaning":"tank surface area (constant)","unit":"$\\text{m}^2$"},{"symbol":"$A_o$","meaning":"orifice area","unit":"$\\text{m}^2$"},{"symbol":"$h_1, h_2$","meaning":"starting and final heads","unit":"$\\text{m}$"}]'::jsonb, 'The outflow slows as the head falls: the last quarter of the depth takes half the total draining time.', 'ESAS', t."id", (SELECT s."id" FROM "SyllabusSubtopic" s JOIN "Topic" t ON t."id" = s."topicId" WHERE t."name" = 'Fluid Mechanics' AND t."subject" = 'ESAS' AND s."normKey" = 'orifices and weirs' AND s."active"), NULL, false, 'PENDING', now(), now()
FROM "Topic" t WHERE t."name" = 'Fluid Mechanics' AND t."subject" = 'ESAS'
ON CONFLICT ("kind", "subject", "name") DO NOTHING;
