SELECT gen_random_uuid()::text, 'formula', '$Q$', 'Rectangular Weir', '$Q = \tfrac23C_d\sqrt{2g}\,LH^{3/2};\qquad \text{Francis: } Q = 1.84(L - 0.1nH)H^{3/2}$', '$\text{m}^3\text{/s}$', 'Flow over a sharp-crested rectangular weir.', '[{"symbol":"$L$","meaning":"crest length","unit":"$\\text{m}$"},{"symbol":"$H$","meaning":"head over the crest","unit":"$\\text{m}$"},{"symbol":"$n$","meaning":"end contractions (0, 1 or 2)","unit":null}]'::jsonb, 'Measure H upstream, beyond the draw-down of the nappe.', 'ESAS', t."id", (SELECT s."id" FROM "SyllabusSubtopic" s JOIN "Topic" t ON t."id" = s."topicId" WHERE t."name" = 'Fluid Mechanics' AND t."subject" = 'ESAS' AND s."normKey" = 'orifices and weirs' AND s."active"), NULL, false, 'PENDING', now(), now()
FROM "Topic" t WHERE t."name" = 'Fluid Mechanics' AND t."subject" = 'ESAS'
