SELECT gen_random_uuid()::text, 'formula', '$Q$', 'Triangular (V-Notch) Weir', '$Q = \tfrac{8}{15}C_d\sqrt{2g}\tan\frac{\theta}{2}H^{5/2};\qquad 90^\circ: Q \approx 1.38H^{5/2}$', '$\text{m}^3\text{/s}$', 'Flow over a V-notch, accurate for small flows.', '[{"symbol":"$\\theta$","meaning":"notch angle","unit":null},{"symbol":"$H$","meaning":"head over the vertex","unit":"$\\text{m}$"}]'::jsonb, 'Flow grows with H^{5/2}: doubling the head gives 5.7 times the flow.', 'ESAS', t."id", (SELECT s."id" FROM "SyllabusSubtopic" s JOIN "Topic" t ON t."id" = s."topicId" WHERE t."name" = 'Fluid Mechanics' AND t."subject" = 'ESAS' AND s."normKey" = 'orifices and weirs' AND s."active"), NULL, false, 'PENDING', now(), now()
