SELECT gen_random_uuid()::text, 'formula', '$Q$', 'Cipolletti Weir', '$Q = 1.859\,LH^{3/2}$', '$\text{m}^3\text{/s}$', 'A trapezoidal weir with 1:4 side slopes, which cancel the end contractions.', '[{"symbol":"$L$","meaning":"crest length","unit":"$\\text{m}$"},{"symbol":"$H$","meaning":"head","unit":"$\\text{m}$"}]'::jsonb, 'No end-contraction correction is needed.', 'ESAS', t."id", (SELECT s."id" FROM "SyllabusSubtopic" s JOIN "Topic" t ON t."id" = s."topicId" WHERE t."name" = 'Fluid Mechanics' AND t."subject" = 'ESAS' AND s."normKey" = 'orifices and weirs' AND s."active"), NULL, false, 'PENDING', now(), now()
