SELECT gen_random_uuid()::text, 'formula', '$R$', 'Hydraulic Radius', '$R = \frac{A}{P_w};\qquad \text{full pipe: } \frac{D}{4};\qquad D_h = 4R$', '$\text{m}$', 'Flow area over wetted perimeter: how "deep" a channel acts.', '[{"symbol":"$A$","meaning":"area","unit":"$\\text{m}^2$"},{"symbol":"$P_w$","meaning":"wetted perimeter","unit":"$\\text{m}$"}]'::jsonb, 'Use D_h = 4R in the Reynolds number and Darcy formula for non-circular ducts.', 'ESAS', t."id", (SELECT s."id" FROM "SyllabusSubtopic" s JOIN "Topic" t ON t."id" = s."topicId" WHERE t."name" = 'Fluid Mechanics' AND t."subject" = 'ESAS' AND s."normKey" = 'open channels' AND s."active"), NULL, false, 'PENDING', now(), now()
