SELECT gen_random_uuid()::text, 'formula', '$v$', 'Manning''s Equation', '$v = \frac{1}{n}R^{2/3}S^{1/2},\qquad Q = \frac{1}{n}AR^{2/3}S^{1/2}\ \text{(SI)}$', '$\text{m/s}$', 'Uniform flow velocity in an open channel.', '[{"symbol":"$n$","meaning":"Manning roughness (concrete ≈ 0.013)","unit":null},{"symbol":"$R$","meaning":"hydraulic radius","unit":"$\\text{m}$"},{"symbol":"$S$","meaning":"channel slope","unit":null}]'::jsonb, 'In English units the 1 becomes 1.486.', 'ESAS', t."id", (SELECT s."id" FROM "SyllabusSubtopic" s JOIN "Topic" t ON t."id" = s."topicId" WHERE t."name" = 'Fluid Mechanics' AND t."subject" = 'ESAS' AND s."normKey" = 'open channels' AND s."active"), NULL, false, 'PENDING', now(), now()
FROM "Topic" t WHERE t."name" = 'Fluid Mechanics' AND t."subject" = 'ESAS'
