SELECT gen_random_uuid()::text, 'formula', '$v$', 'Chezy Equation', '$v = C\sqrt{RS},\qquad C = \frac{R^{1/6}}{n} = \sqrt{\frac{8g}{f}}$', '$\text{m/s}$', 'The older uniform-flow formula; Manning is a special case.', '[{"symbol":"$C$","meaning":"Chezy coefficient","unit":"$\\text{m}^{1/2}\\text{/s}$"},{"symbol":"$R$","meaning":"hydraulic radius","unit":"$\\text{m}$"},{"symbol":"$S$","meaning":"slope","unit":null}]'::jsonb, 'The C–f link connects open-channel and pipe friction.', 'ESAS', t."id", (SELECT s."id" FROM "SyllabusSubtopic" s JOIN "Topic" t ON t."id" = s."topicId" WHERE t."name" = 'Fluid Mechanics' AND t."subject" = 'ESAS' AND s."normKey" = 'open channels' AND s."active"), NULL, false, 'PENDING', now(), now()
