SELECT gen_random_uuid()::text, 'formula', '$y_c$', 'Specific Energy and Critical Depth', '$E = y + \frac{v^2}{2g};\qquad \text{rectangular: } y_c = \sqrt[3]{\frac{q^2}{g}},\quad E_{\min} = \tfrac32y_c$', '$\text{m}$', 'Energy above the channel bottom, and the depth at which it is least for a given flow.', '[{"symbol":"$y$","meaning":"depth","unit":"$\\text{m}$"},{"symbol":"$q$","meaning":"flow per unit width","unit":"$\\text{m}^2\\text{/s}$"}]'::jsonb, 'Below y_c the flow is fast (supercritical), above it slow (subcritical).', 'ESAS', t."id", (SELECT s."id" FROM "SyllabusSubtopic" s JOIN "Topic" t ON t."id" = s."topicId" WHERE t."name" = 'Fluid Mechanics' AND t."subject" = 'ESAS' AND s."normKey" = 'open channels' AND s."active"), NULL, false, 'PENDING', now(), now()
