SELECT gen_random_uuid()::text, 'formula', '$Fr$', 'Froude Number', '$Fr = \frac{v}{\sqrt{gy_h}},\qquad y_h = \frac{A}{T}$', NULL, 'Ratio of flow speed to wave speed: 1 is critical, above 1 supercritical.', '[{"symbol":"$v$","meaning":"mean velocity","unit":"$\\text{m/s}$"},{"symbol":"$y_h$","meaning":"hydraulic depth (area over top width)","unit":"$\\text{m}$"}]'::jsonb, 'A surface wave can travel upstream only when Fr < 1.', 'ESAS', t."id", (SELECT s."id" FROM "SyllabusSubtopic" s JOIN "Topic" t ON t."id" = s."topicId" WHERE t."name" = 'Fluid Mechanics' AND t."subject" = 'ESAS' AND s."normKey" = 'open channels' AND s."active"), NULL, true, 'PENDING', now(), now()
