SELECT gen_random_uuid()::text, 'formula', '$b = 2y$', 'Most Efficient Channel Sections', '$\text{rectangle: } b = 2y,\ R = \frac y2;\qquad \text{trapezoid: half a hexagon (sides at } 60^\circ),\ R = \frac y2$', '$\text{m}$', 'The shapes that carry the most flow for a given area (least wetted perimeter).', '[{"symbol":"$b$","meaning":"bottom width","unit":"$\\text{m}$"},{"symbol":"$y$","meaning":"depth","unit":"$\\text{m}$"}]'::jsonb, 'For every best section, the hydraulic radius is half the depth.', 'ESAS', t."id", (SELECT s."id" FROM "SyllabusSubtopic" s JOIN "Topic" t ON t."id" = s."topicId" WHERE t."name" = 'Fluid Mechanics' AND t."subject" = 'ESAS' AND s."normKey" = 'open channels' AND s."active"), NULL, false, 'PENDING', now(), now()
