SELECT gen_random_uuid()::text, 'formula', '$\eta$', 'Pump and Turbine Efficiency', '$P_{\text{pump shaft}} = \frac{\gamma QH}{\eta},\qquad P_{\text{turbine out}} = \eta\gamma QH$', '$\text{W}$', 'A pump needs more shaft power than it gives the water; a turbine gives less than it takes.', '[{"symbol":"$\\gamma$","meaning":"specific weight","unit":"$\\text{N/m}^3$"},{"symbol":"$Q$","meaning":"flow rate","unit":"$\\text{m}^3\\text{/s}$"},{"symbol":"$H$","meaning":"head","unit":"$\\text{m}$"},{"symbol":"$\\eta$","meaning":"efficiency","unit":null}]'::jsonb, 'Motor input = shaft power ÷ motor efficiency.', 'ESAS', t."id", (SELECT s."id" FROM "SyllabusSubtopic" s JOIN "Topic" t ON t."id" = s."topicId" WHERE t."name" = 'Fluid Mechanics' AND t."subject" = 'ESAS' AND s."normKey" = 'pumps and turbines' AND s."active"), NULL, false, 'PENDING', now(), now()
FROM "Topic" t WHERE t."name" = 'Fluid Mechanics' AND t."subject" = 'ESAS'
ON CONFLICT ("kind", "subject", "name") DO NOTHING;
