SELECT gen_random_uuid()::text, 'formula', '$\frac{Q_2}{Q_1}$', 'Affinity Laws', '$\frac{Q_2}{Q_1} = \frac{N_2D_2^3}{N_1D_1^3}\ \text{or } \frac{N_2}{N_1}\ (\text{same pump}),\quad \frac{H_2}{H_1} = \left(\frac{N_2}{N_1}\right)^2,\quad \frac{P_2}{P_1} = \left(\frac{N_2}{N_1}\right)^3$', NULL, 'How a pump''s flow, head and power change with speed.', '[{"symbol":"$N$","meaning":"speed","unit":"$\\text{rpm}$"},{"symbol":"$D$","meaning":"impeller diameter","unit":"$\\text{m}$"}]'::jsonb, 'For the same pump at a new speed: Q ∝ N, H ∝ N², P ∝ N³. Trimming the impeller: Q ∝ D, H ∝ D², P ∝ D³.', 'ESAS', t."id", (SELECT s."id" FROM "SyllabusSubtopic" s JOIN "Topic" t ON t."id" = s."topicId" WHERE t."name" = 'Fluid Mechanics' AND t."subject" = 'ESAS' AND s."normKey" = 'pumps and turbines' AND s."active"), NULL, true, 'PENDING', now(), now()
