SELECT gen_random_uuid()::text, 'formula', '$N_s$', 'Specific Speed', '$\text{pump: } N_s = \frac{N\sqrt{Q}}{H^{3/4}};\qquad \text{turbine: } N_s = \frac{N\sqrt{P}}{H^{5/4}}$', NULL, 'A shape number that selects the type of pump or turbine.', '[{"symbol":"$N$","meaning":"speed","unit":"$\\text{rpm}$"},{"symbol":"$Q$","meaning":"flow rate","unit":"$\\text{m}^3\\text{/s}$"},{"symbol":"$H$","meaning":"head","unit":"$\\text{m}$"},{"symbol":"$P$","meaning":"power","unit":"$\\text{kW}$"}]'::jsonb, 'Low N_s: radial pumps, Pelton wheels (high head). High N_s: axial pumps, Kaplan turbines (low head).', 'ESAS', t."id", (SELECT s."id" FROM "SyllabusSubtopic" s JOIN "Topic" t ON t."id" = s."topicId" WHERE t."name" = 'Fluid Mechanics' AND t."subject" = 'ESAS' AND s."normKey" = 'pumps and turbines' AND s."active"), NULL, true, 'PENDING', now(), now()
