SELECT gen_random_uuid()::text, 'formula', '$NPSH_A$', 'Net Positive Suction Head', '$NPSH_A = \frac{p_{atm}}{\gamma} - z_s - h_{fs} - \frac{p_v}{\gamma}$', '$\text{m}$', 'Head available at the pump inlet above vapour pressure; it must exceed the pump''s required NPSH to avoid cavitation.', '[{"symbol":"$z_s$","meaning":"suction lift (pump above the water surface)","unit":"$\\text{m}$"},{"symbol":"$h_{fs}$","meaning":"suction-pipe losses","unit":"$\\text{m}$"},{"symbol":"$p_v$","meaning":"vapour pressure of the liquid","unit":"$\\text{Pa}$"}]'::jsonb, 'Hot water has a high vapour pressure: it needs a flooded suction.', 'ESAS', t."id", (SELECT s."id" FROM "SyllabusSubtopic" s JOIN "Topic" t ON t."id" = s."topicId" WHERE t."name" = 'Fluid Mechanics' AND t."subject" = 'ESAS' AND s."normKey" = 'pumps and turbines' AND s."active"), NULL, false, 'PENDING', now(), now()
